// Health check endpoint for Kubernetes readiness probe
app.get('/healthz', async (req, res) => {
  try {
    const { Pool } = require('pg');
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
    });

    // Try to connect to the database
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();

    res.status(200).json({ db: 'ok' });
  } catch (error) {
    // Handle case where pg module is not installed or DB connection fails
    if (error.code === 'MODULE_NOT_FOUND') {
      res.status(503).json({ db: 'error', message: 'PostgreSQL client not available' });
    } else {
      console.error('Health check failed:', error.message);
      res.status(503).json({ db: 'error', message: 'Database unavailable' });
    }
  }
});

