const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/healthz', async (req, res) => {
  try {
    // Extract database host and port from DATABASE_URL
    const dbUrl = process.env.DATABASE_URL || '';
    if (!dbUrl) {
      return res.status(503).json({ db: 'error', message: 'DATABASE_URL not configured' });
    }

    // Parse postgres://user:pass@host:port/db to get host and port
    const urlMatch = dbUrl.match(/postgres:\/\/[^@]+@([^:]+):(\d+)/);
    if (!urlMatch) {
      return res.status(503).json({ db: 'error', message: 'Invalid DATABASE_URL format' });
    }

    const dbHost = urlMatch[1];
    const dbPort = parseInt(urlMatch[2], 10);

    // Attempt to connect to the database port
    const net = require('net');
    const socket = new net.Socket();

    const timeout = 2000; // 2 second timeout

    const connectionPromise = new Promise((resolve, reject) => {
      socket.setTimeout(timeout);
      socket.connect(dbPort, dbHost, () => {
        socket.end();
        resolve(true);
      });

      socket.on('error', (err) => {
        reject(err);
      });

      socket.on('timeout', () => {
        socket.destroy();
        reject(new Error('Connection timeout'));
      });
    });

    await connectionPromise;
    res.status(200).json({ db: 'ok' });
  } catch (error) {
    console.error('Health check failed:', error.message);
    res.status(503).json({ db: 'error', message: 'Database connection failed' });
  }
});

